-- FitAdapt exercise database and TOPSIS criteria (MySQL 8+)
-- Generated by scripts/build_mysql_seed.ts — do not edit by hand.

CREATE DATABASE IF NOT EXISTS fitadapt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fitadapt;

DROP TABLE IF EXISTS exercise_goal_scores, exercise_environments, exercise_equipment, exercise_secondary_muscles, exercises, equipment, criteria;

CREATE TABLE criteria (
  code        VARCHAR(4)   NOT NULL PRIMARY KEY,
  name        VARCHAR(64)  NOT NULL,
  description VARCHAR(255) NOT NULL,
  weight      DECIMAL(5,4) NOT NULL,
  sort_order  TINYINT      NOT NULL
) ENGINE=InnoDB;

CREATE TABLE equipment (
  id    VARCHAR(32) NOT NULL PRIMARY KEY,
  label VARCHAR(64) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE exercises (
  id          VARCHAR(48)  NOT NULL PRIMARY KEY,
  name        VARCHAR(80)  NOT NULL,
  muscle      ENUM('core','chest','back','shoulders','arms','legs','glutes','cardio') NOT NULL,
  difficulty  TINYINT      NOT NULL CHECK (difficulty BETWEEN 1 AND 5),
  kind        ENUM('reps','hold') NOT NULL,
  low_impact  BOOLEAN      NOT NULL DEFAULT 0,
  instruction VARCHAR(255) NOT NULL,
  pose_label  ENUM('jumping_jacks','pull_ups','push_ups','russian_twists','squats') NULL,
  sort_order  SMALLINT     NOT NULL
) ENGINE=InnoDB;

CREATE TABLE exercise_secondary_muscles (
  exercise_id VARCHAR(48) NOT NULL,
  muscle      ENUM('core','chest','back','shoulders','arms','legs','glutes','cardio') NOT NULL,
  PRIMARY KEY (exercise_id, muscle),
  FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE exercise_equipment (
  exercise_id  VARCHAR(48) NOT NULL,
  equipment_id VARCHAR(32) NOT NULL,
  required     BOOLEAN     NOT NULL DEFAULT 0,
  PRIMARY KEY (exercise_id, equipment_id),
  FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE,
  FOREIGN KEY (equipment_id) REFERENCES equipment(id)
) ENGINE=InnoDB;

CREATE TABLE exercise_environments (
  exercise_id VARCHAR(48) NOT NULL,
  environment ENUM('home','gym','outdoors') NOT NULL,
  PRIMARY KEY (exercise_id, environment),
  FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE exercise_goal_scores (
  exercise_id VARCHAR(48) NOT NULL,
  goal        ENUM('lose_weight','gain_muscle','build_abs','target_part','body_build') NOT NULL,
  score       TINYINT     NOT NULL CHECK (score BETWEEN 1 AND 5),
  PRIMARY KEY (exercise_id, goal),
  FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE
) ENGINE=InnoDB;







